import sys
import os
import traceback
import subprocess
import json

def get_git_logs():
    try:
        result = subprocess.run(
            ['git', 'log', '-n', '10', '--oneline'],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout
    except Exception as e:
        return f"Error fetching git logs: {e}"

def main():
    try:
        git_logs = get_git_logs()
        summary = {
            "version": "1.0.0",
            "git_logs": git_logs,
            "description": "Automated release summary generated by TOAI-elegant-lang build tool."
        }
        
        output_dir = os.environ.get('TOAI_WORKSPACE_DIR', '/home/phenox/gemini-sandbox/')
        output_file = os.path.join(output_dir, 'TOAI_Generated', 'release_summary.json')
        os.makedirs(os.path.dirname(output_file), exist_ok=True)
        
        with open(output_file, 'w', encoding='utf-8') as f:
            json.dump(summary, f, indent=2, ensure_ascii=False)
            
        print(f"Successfully generated release summary at {output_file}")
    except Exception as e:
        traceback.print_exc()
        sys.exit(1)

if __name__ == '__main__':
    main()
